/**
 * Minutes service (ws-a §3.7, §4.6, §6.3) — server only.
 *
 * State transitions live in the pure lifecycle module
 * (src/lib/governance/minutes-lifecycle.ts); the six sec 3.5 fields are
 * generated by minutes-draft.ts at meeting close. This service owns
 * persistence, the approval verification (the approval motion must
 * exist, must have closed passed, and must carry minutesApprovalFor =
 * this minutes id — never text parsing, ws-a §6.3), circulation
 * notification, and signing (lock + retention + PDF pipeline).
 *
 * ADAPTER (store): persistence goes through `MinutesStore`;
 * `InMemoryMinutesStore` implements it for local tests; the Firestore
 * implementation is in firestore-stores.ts.
 *
 * ADAPTER (PDF + Drive): signing renders the locked minutes to PDF and
 * uploads to Google Drive kind `governance` (ws-a §3.8) through
 * `MinutesPdfPipeline`. The renderer is src/lib/governance-pdf-export.ts;
 * the Drive upload half is implemented in firestore-stores.ts against
 * the repo drive path. Tests inject a fake pipeline that returns fixed
 * metadata with the real SHA-256 shape.
 *
 * ADAPTER (notification): circulation email goes through
 * `MinutesNotifier` (mailer template minutes_circulated in production).
 */

import {
  applyMinutesEdit,
  approveMinutes,
  circulateMinutes,
  createMinutesRecord,
  isCirculationOverdue,
  signMinutes,
  type MinutesPdfMeta,
  type MinutesRecord,
} from "@/lib/governance/minutes-lifecycle";
import type { MinutesDraftFields } from "@/lib/governance/minutes-draft";
import type { MotionStore } from "./motions";
import { GovernanceServiceError } from "./shared";

export interface MinutesStore {
  getMinutes(id: string): Promise<MinutesRecord | null>;
  saveMinutes(rec: MinutesRecord): Promise<void>;
  listMinutes(): Promise<MinutesRecord[]>;
  getByMeetingId(meetingId: string): Promise<MinutesRecord | null>;
}

export class InMemoryMinutesStore implements MinutesStore {
  private docs = new Map<string, MinutesRecord>();
  private seq = 0;

  nextId(): string {
    return `minutes_${++this.seq}`;
  }

  async getMinutes(id: string): Promise<MinutesRecord | null> {
    return this.docs.get(id) ?? null;
  }

  async saveMinutes(rec: MinutesRecord): Promise<void> {
    this.docs.set(rec.id, rec);
  }

  async listMinutes(): Promise<MinutesRecord[]> {
    return [...this.docs.values()];
  }

  async getByMeetingId(meetingId: string): Promise<MinutesRecord | null> {
    return [...this.docs.values()].find((m) => m.meetingId === meetingId) ?? null;
  }
}

export interface MinutesPdfPipeline {
  /** Render the (about to be) locked record, upload to Drive, return metadata. */
  renderAndUpload(rec: MinutesRecord, signedBy: string, signedAt: Date): Promise<MinutesPdfMeta>;
}

export interface MinutesNotifier {
  circulated(rec: MinutesRecord, attendeeUids: string[]): Promise<void>;
}

export const noopMinutesNotifier: MinutesNotifier = {
  async circulated() {},
};

export interface MinutesDeps {
  store: MinutesStore;
  motions: MotionStore;
  pdfPipeline: MinutesPdfPipeline;
  notifier?: MinutesNotifier;
  newId?: () => string;
}

function err(code: string, status: number, message: string): GovernanceServiceError {
  return new GovernanceServiceError(code, status, message);
}

async function mustGet(deps: MinutesDeps, id: string): Promise<MinutesRecord> {
  const rec = await deps.store.getMinutes(id);
  if (!rec) throw err("minutes_not_found", 404, `No minutes with id ${id}`);
  return rec;
}

/**
 * Generate the auto-draft at meeting close (ws-a §6.3 step 1). The six
 * fields arrive GENERATED from minutes-draft.ts by the caller (the
 * meetings close path); this service never accepts hand-typed field
 * content. Also stamps meeting.minutesId via the returned record id —
 * the meetings service writes that link (its own collection).
 */
export async function generateMinutesDraft(
  deps: MinutesDeps,
  input: { meetingId: string; bodyId: string; fields: MinutesDraftFields; meetingClosedAt: Date },
): Promise<MinutesRecord> {
  const existing = await deps.store.getByMeetingId(input.meetingId);
  if (existing) return existing; // close is idempotent: one draft per meeting
  const rec = createMinutesRecord({
    id: deps.newId ? deps.newId() : `minutes_${input.meetingClosedAt.getTime()}`,
    meetingId: input.meetingId,
    bodyId: input.bodyId,
    fields: input.fields,
    meetingClosedAt: input.meetingClosedAt,
  });
  await deps.store.saveMinutes(rec);
  return rec;
}

/** NGS edit (ws-a §4.6 PATCH): generated fields refuse inside the lifecycle guard. */
export async function editMinutes(
  deps: MinutesDeps,
  input: { minutesId: string; patch: Record<string, unknown>; editorUid: string; at: Date },
): Promise<MinutesRecord> {
  const rec = await mustGet(deps, input.minutesId);
  const next = applyMinutesEdit(rec, input.patch, { by: input.editorUid, at: input.at });
  await deps.store.saveMinutes(next);
  return next;
}

/** Circulate (ws-a §4.6): stamps circulatedAt and notifies attendees. */
export async function circulateMinutesService(
  deps: MinutesDeps,
  input: { minutesId: string; attendeeUids: string[]; at: Date },
): Promise<MinutesRecord> {
  const rec = await mustGet(deps, input.minutesId);
  const next = circulateMinutes(rec, input.at);
  await deps.store.saveMinutes(next);
  if (deps.notifier) await deps.notifier.circulated(next, input.attendeeUids);
  return next;
}

/**
 * Approval link (ws-a §6.3): called by the motions close path (or the
 * minutes route) when a motion carrying minutesApprovalFor closes. The
 * approval is verified against the actual motion record: it must be
 * closed_passed AND its minutesApprovalFor must name THIS minutes doc.
 */
export async function linkMinutesApproval(
  deps: MinutesDeps,
  input: { minutesId: string; approvalMotionId: string; at: Date },
): Promise<MinutesRecord> {
  const rec = await mustGet(deps, input.minutesId);
  const motion = await deps.motions.getMotion(input.approvalMotionId);
  if (!motion || motion.minutesApprovalFor !== input.minutesId) {
    throw err(
      "minutes_not_approved",
      422,
      "The named motion does not approve these minutes (minutesApprovalFor mismatch)",
    );
  }
  const next = approveMinutes(rec, {
    approvalMotionId: motion.id,
    approvedInMeetingId: motion.meetingId ?? "",
    approvalMotionStatus: motion.status,
    at: input.at,
  });
  await deps.store.saveMinutes(next);
  return next;
}

/**
 * Sign and lock (ws-a §4.6): requires an approved record (the lifecycle
 * guard refuses otherwise with 422 minutes_not_approved), renders and
 * uploads the PDF of the locked record, and stores the Drive metadata +
 * SHA-256 hash with retentionUntil = signedAt + 10 years.
 */
export async function signMinutesService(
  deps: MinutesDeps,
  input: { minutesId: string; signedBy: string; at: Date },
): Promise<{ record: MinutesRecord; pdf: MinutesPdfMeta }> {
  const rec = await mustGet(deps, input.minutesId);
  // Pre-check approval BEFORE rendering/uploading anything: an unapproved
  // record must never produce a Drive file (the lifecycle sign guard then
  // re-validates completeness and the approved state).
  if (rec.status !== "approved" || !rec.approvalMotionId) {
    throw err("minutes_not_approved", 422, "Minutes must be approved by a motion at the next meeting before they can be signed");
  }
  // Render from the record AS IT WILL BE LOCKED (same fields, signed stamps).
  const pdf = await deps.pdfPipeline.renderAndUpload(rec, input.signedBy, input.at);
  const next = signMinutes(rec, { signedBy: input.signedBy, at: input.at, pdf });
  await deps.store.saveMinutes(next);
  return { record: next, pdf };
}

/** T2 scan helper (ws-a §6.6): records whose circulation is overdue at `now`. */
export async function listOverdueMinutes(deps: MinutesDeps, now: Date): Promise<MinutesRecord[]> {
  const all = await deps.store.listMinutes();
  return all.filter((m) => isCirculationOverdue(m, now));
}

/** Flag overdue records (T2 write path): stamps circulationOverdue true. */
export async function flagOverdueMinutes(
  deps: MinutesDeps,
  now: Date,
): Promise<{ flagged: number }> {
  const overdue = await listOverdueMinutes(deps, now);
  let flagged = 0;
  for (const rec of overdue) {
    if (!rec.circulationOverdue) {
      await deps.store.saveMinutes({ ...rec, circulationOverdue: true, updatedAt: now });
      flagged += 1;
    }
  }
  return { flagged };
}
